export const uuid=()=>globalThis.crypto.randomUUID();
export const money=p=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:p%100?2:0}).format(p/100);
export const paise=v=>{const s=String(v).trim();if(!/^\d+(\.\d{1,2})?$/.test(s))throw Error('Enter a positive amount with at most 2 decimal places.');const [a,b='']=s.split('.');const n=Number(a)*100+Number(b.padEnd(2,'0'));if(!Number.isSafeInteger(n)||n>100000000)throw Error('Amount is too large.');return n;};
const product=(id,name,category,price,art,tint,extra={})=>({id,name,category,price,art,tint,active:true,soldOut:false,...extra});
const menu=(id,name,category,art,tint,extra={})=>product(id,name,category,null,art,tint,extra);
