export function initialState(){return {version:1,revision:0,mode:'live',pin:null,config:{menuVersion:2,stallName:'Packet Pataka',stallNumber:'10',eventDate:'2026-11-04',target:514000,promo:1000,promoMinimum:0,operator:'Team Pataka',operators:['Team Pataka','Cashier 1','Cashier 2','Games crew'],accent:'#FFDD35',inventory:false,stock:{small:50,large:50,pizza:0,cocaCola:0,sprite:0,fanta:0},flavours:["Lay’s Classic Salted","Lay’s Magic Masala","Lay’s Cream & Onion","Lay’s Tomato Tango","Kurkure Masala Munch","Kurkure Chilli Chatka","Bingo Mad Angles","Bingo Tedhe Medhe"],addons:[],games:[{id:'wheel',name:'Spin the Wheel',fee:0},{id:'coin',name:'Coin in the Bucket',fee:0}],products:boardMenu()},live:session(),demo:session()};}
export function migrate(state){if(state?.config?.menuVersion>=2)return state;const sessions=[state?.live,state?.demo].filter(Boolean);const hasRecords=sessions.some(s=>s.orders?.length||s.payments?.length||s.games?.length||s.expenses?.length);if(hasRecords)return state;state.config.products=boardMenu();state.config.stock={small:50,large:50,pizza:0,cocaCola:0,sprite:0,fanta:0};state.config.addons=[];state.config.menuVersion=2;for(const s of sessions){s.draft=[];s.draftPromo=false;s.draftId=uuid();}return state;}
export function session(){return {started:false,orders:[],payments:[],games:[],expenses:[],audit:[],milestones:{},draft:[],draftPromo:false,draftId:uuid()};}
export function integer(n,min=0){if(!Number.isSafeInteger(n)||n<min)throw Error('Invalid whole number.');return n;}
export function unitPrice(p,c,extra=[]){if(p.bundle)return p.price;const base=p.base?c.products.find(x=>x.id===p.base):p;if(base?.price==null)return null;let price=integer(base.price);for(const id of new Set([...(p.addons||[]),...extra])){const a=c.addons.find(x=>x.id===id);if(!a)return null;price+=integer(a.price);}return price;}
export function makeLine(c,id,{quantity=1,addons=[],flavour=''}={}){const p=c.products.find(x=>x.id===id);if(!p||!p.active||p.soldOut||p.base&&c.products.find(x=>x.id===p.base)?.soldOut)throw Error('This item is unavailable.');integer(quantity,1);if(quantity>999)throw Error('Maximum quantity is 999.');const price=unitPrice(p,c,addons);if(price===null)throw Error('Confirm this product’s price in Menu & prices first.');const included=[...new Set([...(p.addons||[]),...addons])];let stock={};if(p.bundle){for(const b of p.bundle){const component=c.products.find(x=>x.id===b.productId);if(!component||!component.active||component.soldOut)throw Error('A combo component is unavailable.');integer(b.quantity,1);const key=component.stockKey;if(key)stock[key]=(stock[key]||0)+b.quantity*(component.stockUnits||1);}}else if(p.stockKey)stock[p.stockKey]=p.stockUnits||1;return {id:uuid(),productId:p.id,name:p.name,category:p.category,size:p.size||'',flavour,addons:included.map(id=>({...c.addons.find(a=>a.id===id)})),quantity,unitPrice:price,lineTotal:price*quantity,stock,bundle:p.bundle?structuredClone(p.bundle):null};}
export function totals(lines,c,promo=false){const subtotal=lines.reduce((s,l)=>s+integer(l.unitPrice)*integer(l.quantity,1),0);const discount=promo&&subtotal>=c.promoMinimum?Math.min(c.promo,subtotal):0;return {subtotal,discount,total:subtotal-discount};}
export function netFor(s,entityId){return s.payments.filter(p=>p.entityId===entityId).reduce((n,p)=>n+p.amount,0);}
export function stockUsed(s){const used={};for(const o of s.orders.filter(o=>o.status!=='void'))for(const l of o.items)for(const [key,n]of Object.entries(l.stock||{}))used[key]=(used[key]||0)+n*l.quantity;return used;}
export function checkStock(s,c,items){if(!c.inventory)return;const used=stockUsed(s);for(const l of items)for(const [key,n]of Object.entries(l.stock||{}))used[key]=(used[key]||0)+n*l.quantity;for(const [key,n]of Object.entries(used))if(n>(c.stock[key]||0))throw Error(`${key} stock is insufficient. Check the order or update stock.`);}
export function audit(s,type,entityId,operator,details,now=new Date().toISOString()){s.audit.push({id:uuid(),type,entityId,operator,details,at:now});}
export function createOrder(s,c,{id,items,promo=false,method='Cash',pending=false,cashReceived=null},now=new Date().toISOString()){
 const exists=s.orders.find(x=>x.id===id);if(exists)return exists;
 if(!items.length)throw Error('Add an item before checkout.');if(!['Cash','UPI','Other'].includes(method))throw Error('Choose a payment method.');
 for(const l of items){const p=c.products.find(p=>p.id===l.productId);if(!p||!p.active||p.soldOut||p.base&&c.products.find(x=>x.id===p.base)?.soldOut)throw Error(`${l.name} is unavailable.`);if(p.bundle&&p.bundle.some(b=>{const x=c.products.find(x=>x.id===b.productId);return !x||!x.active||x.soldOut;}))throw Error('A combo component is unavailable.');if(unitPrice(p,c)===null)throw Error(`${l.name} needs a confirmed price.`);integer(l.unitPrice);integer(l.quantity,1);}
 checkStock(s,c,items);const t=totals(items,c,promo);if(cashReceived!==null&&method==='Cash'&&cashReceived<t.total)throw Error('Cash received is less than the total.');
 const o={id,number:s.orders.length+1,at:now,operator:c.operator,items:structuredClone(items).map(l=>({...l,lineTotal:l.unitPrice*l.quantity})),...t,method,status:pending?'pending':'paid',cashReceived:method==='Cash'?cashReceived:null,change:method==='Cash'&&cashReceived!==null?cashReceived-t.total:0};s.orders.push(o);
 if(!pending)s.payments.push({id:uuid(),entityId:id,kind:'order',amount:t.total,method,at:now});audit(s,'order-created',id,c.operator,{status:o.status,total:o.total},now);s.draft=[];s.draftPromo=false;s.draftId=uuid();refreshMilestones(s,c,now);return o;
}
export function markPaid(s,c,id,method,now=new Date().toISOString()){const o=s.orders.find(x=>x.id===id);if(!o||o.status!=='pending')throw Error('This order is no longer pending.');if(!['Cash','UPI','Other'].includes(method))throw Error('Choose a payment method.');o.status='paid';o.method=method;s.payments.push({id:uuid(),entityId:id,kind:'order',amount:o.total,method,at:now});audit(s,'payment-confirmed',id,c.operator,{amount:o.total,method},now);refreshMilestones(s,c,now);}
export function correctOrder(s,c,id,{type,amount,reason},now=new Date().toISOString()){const o=s.orders.find(x=>x.id===id);if(!o||o.status==='void')throw Error('Order is already void or missing.');if(!reason?.trim())throw Error('A correction reason is required.');if(!['void','refund'].includes(type))throw Error('Invalid correction.');const balance=netFor(s,id);const value=type==='void'?balance:integer(amount,1);if(value>balance||type==='refund'&&o.status==='pending')throw Error('Refund exceeds the collected balance.');if(value)s.payments.push({id:uuid(),entityId:id,kind:'refund',amount:-value,method:o.method,at:now});o.status=type==='void'?'void':balance===value?'refunded':'partial';audit(s,type,id,c.operator,{amount:value,reason:reason.trim()},now);refreshMilestones(s,c,now);}
export function addGame(s,c,{id,gameId,prize='',method='Cash'},now=new Date().toISOString()){if(s.games.some(g=>g.id===id))return;const g=c.games.find(g=>g.id===gameId);if(!g)throw Error('Unknown game.');integer(g.fee);if(!['Cash','UPI','Other'].includes(method))throw Error('Choose a payment method.');s.games.push({id,gameId,name:g.name,fee:g.fee,prize,method,operator:c.operator,at:now,void:false});if(g.fee)s.payments.push({id:uuid(),entityId:id,kind:'game',amount:g.fee,method,at:now});audit(s,'game-recorded',id,c.operator,{fee:g.fee},now);refreshMilestones(s,c,now);}
export function voidGame(s,c,id,reason){const g=s.games.find(g=>g.id===id);if(!g||g.void)throw Error('Game already reversed.');if(!reason?.trim())throw Error('A reason is required.');g.void=true;const amount=netFor(s,id);if(amount)s.payments.push({id:uuid(),entityId:id,kind:'refund',amount:-amount,method:g.method,at:new Date().toISOString()});audit(s,'game-void',id,c.operator,{amount,reason});refreshMilestones(s,c);}
const hourFormatter=new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',hour:'2-digit',hour12:false});
export function report(s,c){const orderIds=new Set(s.orders.map(o=>o.id)),gameIds=new Set(s.games.map(g=>g.id)),balances={};for(const p of s.payments)balances[p.entityId]=(balances[p.entityId]||0)+p.amount;const eligible=s.orders.filter(o=>['paid','partial'].includes(o.status));const paid=s.orders.filter(o=>o.status!=='pending');const collected=s.payments.reduce((n,p)=>n+p.amount,0);const food=s.payments.filter(p=>orderIds.has(p.entityId)).reduce((n,p)=>n+p.amount,0);const methods=Object.fromEntries(['Cash','UPI','Other'].map(m=>[m,s.payments.filter(p=>p.method===m).reduce((n,p)=>n+p.amount,0)]));const units=eligible.reduce((n,o)=>n+o.items.reduce((k,l)=>k+l.quantity,0),0);const best={},categories={},hourly={};for(const o of eligible)for(const l of o.items){best[l.productId]??={name:l.name,units:0,revenue:0};best[l.productId].units+=l.quantity;best[l.productId].revenue+=l.lineTotal;categories[l.category]=(categories[l.category]||0)+l.lineTotal;}for(const p of s.payments){const hour=hourFormatter.format(new Date(p.at));hourly[hour]=(hourly[hour]||0)+p.amount;}return {collected,food,methods,orders:eligible.length,units,average:eligible.length?Math.round(eligible.reduce((n,o)=>n+(balances[o.id]||0),0)/eligible.length):0,gross:paid.reduce((n,o)=>n+o.subtotal,0),discounts:paid.reduce((n,o)=>n+o.discount,0),refunds:-s.payments.filter(p=>p.amount<0).reduce((n,p)=>n+p.amount,0),games:s.games.filter(g=>!g.void).length,gameIncome:s.payments.filter(p=>gameIds.has(p.entityId)).reduce((n,p)=>n+p.amount,0),expenses:s.expenses.reduce((n,e)=>n+e.amount,0),remaining:Math.max(0,c.target-collected),above:Math.max(0,collected-c.target),percent:Math.max(0,Math.min(100,collected/c.target*100)),best:Object.values(best).sort((a,b)=>b.units-a.units),categories,hourly};}
export function refreshMilestones(s,c,now=new Date().toISOString()){const r=report(s,c);const rules={spark:r.orders>=1,game:r.games>=1,crowd:r.orders>=50,big:r.collected>=c.target};for(const [id,active]of Object.entries(rules)){const old=s.milestones[id];s.milestones[id]={active,unlockedAt:old?.unlockedAt||(active?now:null),reference:old?.reference||(active?(id==='game'?s.games.at(-1)?.id:s.orders.at(-1)?.id):null),updatedAt:old?.active===active?old.updatedAt:now};}return rules;}
export function validateBackup(v){
 const fail=message=>{throw Error(message);};
 const id=x=>{if(typeof x!=='string'||!/^[a-zA-Z0-9_-]{1,100}$/.test(x))fail('Invalid record identifier.');};
 const str=(x,max=500)=>{if(typeof x!=='string'||x.length>max)fail('Invalid text field.');};
 const time=x=>{if(typeof x!=='string'||!Number.isFinite(Date.parse(x)))fail('Invalid record timestamp.');};
 const unique=items=>{const seen=new Set();for(const x of items){id(x.id);if(seen.has(x.id))fail('Duplicate identifier.');seen.add(x.id);}};
 const line=l=>{id(l.id);id(l.productId);str(l.name);str(l.category);str(l.flavour);str(l.size);integer(l.unitPrice);integer(l.quantity,1);if(l.quantity>999||l.lineTotal!==l.unitPrice*l.quantity)fail('Invalid line total.');if(!Array.isArray(l.addons)||!l.stock||typeof l.stock!=='object')fail('Invalid line snapshot.');for(const a of l.addons){id(a.id);str(a.name);integer(a.price);}for(const [k,n]of Object.entries(l.stock)){id(k);integer(n,1);}};
 if(!v||v.version!==1||!['live','demo'].includes(v.mode)||!v.config)fail('Unsupported backup file.');
 const c=v.config;integer(c.target,1);integer(c.promo);integer(c.promoMinimum);for(const k of ['stallName','stallNumber','eventDate','operator'])str(c[k]);if(!/^#[a-fA-F0-9]{6}$/.test(c.accent))fail('Invalid accent color.');
 if(!Array.isArray(c.products)||!Array.isArray(c.addons)||!Array.isArray(c.flavours)||!c.flavours.length||!Array.isArray(c.operators)||!Array.isArray(c.games)||!c.stock)fail('Invalid catalog.');
 for(const x of [...c.flavours,...c.operators])str(x);unique(c.products);unique(c.addons);unique(c.games);
 for(const p of c.products){str(p.name);str(p.category);str(p.art);str(p.tint);if(p.price!==null)integer(p.price);if(p.base&&!c.products.some(x=>x.id===p.base&&!x.base&&!x.bundle))fail('Invalid preset base.');if(p.addons)for(const a of p.addons)if(!c.addons.some(x=>x.id===a))fail('Missing preset topping.');if(p.bundle){if(!Array.isArray(p.bundle)||!p.bundle.length)fail('Empty combo.');for(const b of p.bundle){integer(b.quantity,1);if(!c.products.some(x=>x.id===b.productId&&!x.bundle))fail('Missing combo component.');}}if(p.stockUnits!==undefined)integer(p.stockUnits,1);}
 for(const a of c.addons){str(a.name);integer(a.price);}for(const g of c.games){str(g.name);integer(g.fee);}for(const [k,n]of Object.entries(c.stock)){id(k);integer(n);}if(v.pin&&(typeof v.pin.hash!=='string'||!/^\w{64}$/.test(v.pin.hash)||typeof v.pin.salt!=='string'))fail('Invalid PIN record.');
 for(const mode of ['live','demo']){const s=v[mode];for(const key of ['orders','payments','games','expenses','audit','draft'])if(!Array.isArray(s?.[key]))fail('Incomplete backup.');for(const key of ['orders','payments','games','expenses','audit'])unique(s[key]);id(s.draftId);for(const l of s.draft)line(l);s.milestones??={};
  const entities=new Set();for(const o of s.orders){entities.add(o.id);time(o.at);str(o.operator);integer(o.number,1);integer(o.total);integer(o.discount);integer(o.subtotal);if(!Array.isArray(o.items)||!o.items.length)fail('Empty order.');for(const l of o.items)line(l);if(o.items.reduce((n,l)=>n+l.lineTotal,0)!==o.subtotal||o.subtotal-o.discount!==o.total)fail('Invalid order totals.');if(!['paid','partial','refunded','void','pending'].includes(o.status)||!['Cash','UPI','Other'].includes(o.method))fail('Invalid order state.');}
  for(const g of s.games){if(entities.has(g.id))fail('Duplicate ledger entity.');entities.add(g.id);id(g.gameId);str(g.name);str(g.prize);str(g.operator);time(g.at);integer(g.fee);if(!['Cash','UPI','Other'].includes(g.method))fail('Invalid game payment method.');}
  const balances={};for(const p of s.payments){time(p.at);if(!Number.isSafeInteger(p.amount)||!['Cash','UPI','Other'].includes(p.method)||!entities.has(p.entityId))fail('Invalid payment ledger.');balances[p.entityId]=(balances[p.entityId]||0)+p.amount;}
  for(const o of s.orders){const n=balances[o.id]||0;if(n<0||n>o.total||['void','pending','refunded'].includes(o.status)&&n!==0||o.status==='paid'&&n!==o.total||o.status==='partial'&&(n<=0||n>=o.total))fail('Payment balance mismatch.');}
  for(const g of s.games)if((balances[g.id]||0)!==(g.void?0:g.fee))fail('Game payment mismatch.');for(const e of s.expenses){integer(e.amount);time(e.at);str(e.description);str(e.category);str(e.operator);}for(const a of s.audit){time(a.at);str(a.type);str(a.operator);if(!a.details||typeof a.details!=='object')fail('Invalid audit entry.');}refreshMilestones(s,c);
 }
 return v;
}
